    public static function action(string $code): string
    {
        if (isset(self::ACTIONS[$code])) return self::ACTIONS[$code];
        if (preg_match('/[\x{0600}-\x{06ff}]/u',$code)) return str_replace('(API)','(الموبايل)',$code);
        if (preg_match('/^(\w+)Controller\.(\w+)$/D',$code,$m)) {
            $module=self::MODULES[$m[1]]??'النظام';$method=preg_replace('/Api$/','',$m[2]);
            if(isset(self::SUBJECTS[$method])) return self::SUBJECTS[$method];
            $verbs=['update'=>'تعديل','store'=>'إضافة','create'=>'إنشاء','delete'=>'حذف','destroy'=>'حذف','remove'=>'إزالة','list'=>'عرض','get'=>'عرض','show'=>'عرض','export'=>'تصدير','import'=>'استيراد','request'=>'تقديم طلب','decide'=>'اتخاذ قرار بشأن','set'=>'تعيين','deliver'=>'تسليم','return'=>'إرجاع','issue'=>'تسليم','save'=>'حفظ','edit'=>'فتح نموذج تعديل'];
            foreach($verbs as $prefix=>$verb) if(str_starts_with($method,$prefix)) {
                $subject=lcfirst(substr($method,strlen($prefix)));
                return $verb.' '.(self::SUBJECTS[$subject]??$module);
            }
            return match($method){'index','page','section','form'=>'عرض '.$module,'countJson'=>'تحديث عدد عناصر '.$module,default=>'إجراء في '.$module};
        }
        return $code==='unmatched'?'طلب عنوان غير موجود':'عملية مسجّلة في النظام';
    }
    public static function field(string $key): string {return self::FIELDS[$key]??(preg_match('/[\x{0600}-\x{06ff}]/u',$key)?$key:'حقل إضافي');}
    public static function entity(string $key): string
    {
        if(isset(self::ENTITIES[$key]))return self::ENTITIES[$key];
        if(str_starts_with($key,'/')) {
            $labels=[];foreach(explode('/',trim($key,'/')) as $part)if(isset(self::ENTITIES[$part]))$labels[]=self::ENTITIES[$part];
            return $labels?implode(' ← ',array_unique($labels)):'صفحة أو خدمة بالنظام';
        }
        return $key===''?'غير محدد':(preg_match('/[\x{0600}-\x{06ff}]/u',$key)?$key:'سجل آخر بالنظام');
    }
    public static function value(?string $value, string $field=''): string
    {
        $safe=SystemActivityService::safeDetails($value,$field);
        if($safe==='' || $value===null)return 'غير محدد';
        if(in_array($field,['geofence_exempt','housing_exempt'],true) && in_array($safe,['0','1'],true))return $safe==='1'?'نعم':'لا';
        $values=['active'=>'نشط','inactive'=>'غير نشط','resigned'=>'مستقيل','terminated'=>'منتهية خدمته','suspended'=>'موقوف','archived'=>'مؤرشف','open'=>'مفتوح','closed'=>'مغلق','fixed'=>'ثابت','flexible'=>'مرن','approved'=>'موافق عليه','pending'=>'بانتظار الموافقة','rejected'=>'مرفوض','disabled'=>'الدخول معطّل','disabled: resigned'=>'الدخول معطّل بسبب الاستقالة','returned'=>'مُعاد','damaged'=>'تالف','lost'=>'مفقود','all'=>'الجميع','employee'=>'موظف','department'=>'قسم','branch'=>'فرع','yarmouk'=>'اليرموك','none'=>'لا يوجد','manual'=>'يدوي','automatic'=>'تلقائي'];
        // Do not translate ordinary names, comments or other user-entered text.
        if(in_array($field,['status','attendance_type','file_status','user_access','housing_type','target','payroll_absence_mode'],true))return $values[$safe]??$safe;
        if($field==='weekly_off_day')return ['sunday'=>'الأحد','monday'=>'الاثنين','tuesday'=>'الثلاثاء','wednesday'=>'الأربعاء','thursday'=>'الخميس','friday'=>'الجمعة','saturday'=>'السبت'][strtolower($safe)]??$safe;
        if(in_array($field,['manager_id','branch_id','shift_id','job_id','department_id','cost_center_id','document_id','contract_id'],true) && ctype_digit($safe))return self::field($field).' رقم '.$safe;
        return $safe;
    }
    public static function notes(string $text): string
    {
        $text=SystemActivityService::safeDetails($text);
        $json=json_decode($text,true);
        if(is_array($json)) {
            $lines=[];foreach($json as $key=>$value)$lines[]=self::field((string)$key).': '.(is_scalar($value)||$value===null?self::value($value===null?null:(string)$value,(string)$key):self::notes(json_encode($value,JSON_UNESCAPED_UNICODE)));
            return implode("\n",$lines);
        }
        // Only translate known structured key/value prefixes. Leave free-form evidence intact.
        return preg_replace_callback('/(?<![\w])('.implode('|',array_map('preg_quote',array_keys(self::FIELDS))).')\s*[:=]\s*/u',fn($m)=>self::field($m[1]).': ',$text);
    }
    public static function details(array $row): string
    {
        $lines=[];
        if($row['source']==='employees') {
            $lines[]='الحقل المعدّل: '.self::field((string)$row['field_name']);
            $lines[]='قبل التغيير: '.self::value($row['old_value'],(string)$row['field_name']);
            $lines[]='بعد التغيير: '.self::value($row['new_value'],(string)$row['field_name']);
        }
        if(!empty($row['details']))$lines[]=self::notes($row['details']);
        if(!empty($row['method'])) {
            $lines[]='نوع الاتصال: '.(['GET'=>'طلب عرض أو قراءة','POST'=>'إرسال إجراء أو بيانات','PUT'=>'استبدال بيانات','PATCH'=>'تحديث بيانات','DELETE'=>'طلب حذف'][$row['method']]??'اتصال بالنظام');
            $status=(int)$row['http_status'];
            $lines[]='نتيجة الاتصال: '.match(true){$status===401=>'يتطلب تسجيل الدخول',$status===403=>'الصلاحية غير كافية',$status===404=>'العنوان المطلوب غير موجود',$status===409=>'تعارض مع الحالة الحالية',$status===422=>'البيانات غير مقبولة',$status===429=>'تجاوز عدد المحاولات المسموح',$status>=500=>'تعذر إكمال الطلب بسبب خطأ في الخادم',$status>=400=>'لم يُقبل الطلب',$status>=300=>'تحويل إلى صفحة أخرى',default=>'تمت الاستجابة للاتصال'};
            $lines[]='زمن الاستجابة: '.(int)$row['duration_ms'].' مللي ثانية';
        }
        if(!empty($row['ip']))$lines[]='عنوان الاتصال: '.$row['ip'];
        if(!empty($row['device']))$lines[]='نوع الجهاز: '.(['iOS'=>'آيفون / آيباد','iPhone'=>'آيفون','iPad'=>'آيباد','Android'=>'أندرويد','Windows'=>'ويندوز','Mac'=>'ماك','Linux'=>'لينكس','Mobile'=>'هاتف محمول','Web'=>'متصفح ويب','Other'=>'غير محدد'][$row['device']]??'غير محدد');
        return $lines?implode("\n",$lines):'لا توجد تفاصيل إضافية محفوظة لهذا الحدث.';
    }
}
